<script lang="ts">
  import { requests } from '$lib/stores/requests';
  import { requestBackendAvailable } from '$lib/wasm';
  import { conversations } from '$lib/stores/conversations';
  let pending=$derived($requests.views.filter(v=>v.consent==='incomingPending'||v.consent==='outgoingPending'));
  let drafts=$derived($requests.drafts.filter(d=>!d.archived && d.outcome?.type!=='requestSent'));
  function title(id:string) { return $conversations.items.find(c=>c.id===id)?.displayName || 'Message request'; }
</script>
<section class="request-inbox" aria-label="Message requests">
  <header><div><p class="eyebrow">YOUR INBOX, YOUR CHOICE</p><h1>Message requests</h1><p>Read an encrypted introduction before deciding to chat.</p></div><button onclick={()=>requests.load()} disabled={$requests.loading || !requestBackendAvailable}>Refresh</button></header>
  {#if !requestBackendAvailable}<p class="notice">Encrypted requests aren’t available in this browser yet. Local drafts stay on this screen.</p>{/if}
  {#if requestBackendAvailable}<details class="notice"><summary>Receive encrypted requests on this device · {$requests.deliveryEnabled === null ? 'Unconfirmed' : $requests.deliveryEnabled ? 'On' : 'Off'}</summary><p>Enabling publishes encryption keys for this device. Turning it off stops new request delivery; existing requests stay available.</p><button disabled={$requests.busy} onclick={()=>requests.setDeliveryEnabled(true)}>Enable delivery</button> <button disabled={$requests.busy} onclick={()=>requests.setDeliveryEnabled(false)}>Turn off delivery</button><p>Retry the same choice if its confirmation is unavailable.</p></details>{/if}
  {#if $requests.notice}<p class="notice" role="status">{$requests.notice}</p>{/if}
  {#if $requests.error}<p class="notice error" role="alert">{$requests.error}</p>{/if}
  {#if $requests.loading}<p class="muted" aria-live="polite">Checking requests…</p>{/if}
  {#if pending.length===0 && drafts.length===0 && !$requests.loading}<div class="empty"><span class="empty-symbol" aria-hidden="true">✉</span><h2>A little space for introductions</h2><p>New messages from people you haven’t accepted will appear here.</p></div>{/if}
  {#if pending.length}<h2 class="section-label">Introductions</h2><div class="rows">{#each pending as view(view.conversationId)}<button class="row" onclick={()=>requests.selectRequest(view.conversationId)}><span class="avatar" aria-hidden="true">{view.consent==='incomingPending'?'↙':'↗'}</span><span class="row-body"><strong>{title(view.conversationId)}</strong><span>{view.preview?.type==='ready'?view.preview.text:'Encrypted content unavailable on this device'}</span></span><small>{view.consent==='incomingPending'?'Review':'Request sent'}</small></button>{/each}</div>{/if}
  {#if drafts.length}<h2 class="section-label">Drafts & delivery</h2><div class="rows">{#each drafts as draft(draft.input.draftId)}<button class="row" onclick={()=>requests.selectDraft(draft.input.draftId)}><span class="avatar draft" aria-hidden="true">✎</span><span class="row-body"><strong>{draft.recipientLabel}</strong><span>{draft.input.text || 'Write an introduction'}</span></span><small>{draft.phase==='draft'?'Only you':'Check delivery'}</small></button>{/each}</div>{/if}
</section>
<style>
.request-inbox{width:100%;max-width:860px;margin:0 auto;padding:48px 40px;overflow:auto}header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:30px}h1{font-size:30px;letter-spacing:-.04em;margin:6px 0 10px;color:var(--text-primary)}header p,.muted,.empty p{color:var(--text-secondary);line-height:1.6}p.eyebrow{font-size:10px;letter-spacing:.16em;font-weight:700;color:var(--accent)}button{font:inherit;cursor:pointer;border:1px solid var(--border);border-radius:10px;background:var(--bg-card);color:var(--text-primary);padding:10px 16px}button:disabled{opacity:.5;cursor:default}.notice{padding:16px;border:1px solid var(--border);border-radius:12px;color:var(--text-secondary);line-height:1.5}.error{color:#e7958d}.empty{text-align:center;padding:65px 20px}.empty-symbol{display:inline-grid;place-items:center;width:76px;height:76px;font-size:34px;border:1px solid var(--border);border-radius:24px;color:var(--accent);margin-bottom:20px}.empty h2{font-size:20px}.section-label{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--text-tertiary);margin:28px 0 12px}.rows{border:1px solid var(--border);border-radius:14px;overflow:hidden}.row{width:100%;display:flex;align-items:center;gap:16px;text-align:left;border:0;border-radius:0;padding:18px;background:var(--bg-secondary)}.row+.row{border-top:1px solid var(--border)}.row:hover{background:var(--bg-hover)}.row-body{min-width:0;flex:1;display:grid;gap:6px}.row-body strong{font-size:14px}.row-body>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;color:var(--text-secondary)}small{font-size:11px;color:var(--text-tertiary);white-space:nowrap}.avatar{width:40px;height:40px;display:grid;place-items:center;border-radius:13px;background:var(--bg-card);color:var(--accent);font-size:22px}.draft{color:var(--text-secondary)}@media(max-width:640px){.request-inbox{padding:24px 18px}header{align-items:flex-start}h1{font-size:25px}.row{gap:10px;padding:14px}small{max-width:70px;white-space:normal}}
</style>
